#include <bits/stdc++.h>
using namespace std;
typedef __int128 i128;  // lengths can have ~36 digits; sums of 13 differences still fit

i128 parse(const string &s) { i128 r = 0; for (char c : s) r = r * 10 + (c - '0'); return r; }

string show(i128 v) {
    if (v == 0) return "0";
    string s;
    for (; v > 0; v /= 10) s += char('0' + (int)(v % 10));
    reverse(s.begin(), s.end());
    return s;
}

int main() {
    int n;
    cin >> n;
    vector<i128> ramu(n), sonu(n);
    string t;
    for (auto &x : ramu) { cin >> t; x = parse(t); }
    for (auto &x : sonu) { cin >> t; x = parse(t); }
    // dp[mask][last]: best sum for a valid prefix using mask and ending with sonu[last]; -1 = unreachable.
    vector<vector<i128>> dp(1 << n, vector<i128>(n, -1));
    for (int j = 0; j < n; j++) dp[1 << j][j] = 0;
    for (int mask = 1; mask < (1 << n); mask++) {
        int pos = __builtin_popcount(mask) - 1;
        if (pos == n - 1) continue;
        bool rise = ramu[pos] < ramu[pos + 1];
        for (int last = 0; last < n; last++) {
            i128 score = dp[mask][last];
            if (score < 0) continue;
            for (int nxt = 0; nxt < n; nxt++) {
                if (mask >> nxt & 1) continue;
                if ((sonu[last] < sonu[nxt]) != rise) continue;
                i128 diff = sonu[last] > sonu[nxt] ? sonu[last] - sonu[nxt] : sonu[nxt] - sonu[last];
                i128 &slot = dp[mask | 1 << nxt][nxt];
                slot = max(slot, score + diff);
            }
        }
    }
    i128 best = -1;
    for (int j = 0; j < n; j++) best = max(best, dp[(1 << n) - 1][j]);
    cout << show(best) << "\n";
}

import java.io.*;
import java.math.BigInteger;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        StreamTokenizer st = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        st.resetSyntax();
        st.wordChars('!', '~');
        st.whitespaceChars(0, ' ');
        st.nextToken();
        int n = Integer.parseInt(st.sval);
        // Lengths may exceed 64 bits, so use BigInteger throughout.
        BigInteger[] ramu = new BigInteger[n], sonu = new BigInteger[n];
        for (int i = 0; i < n; i++) { st.nextToken(); ramu[i] = new BigInteger(st.sval); }
        for (int i = 0; i < n; i++) { st.nextToken(); sonu[i] = new BigInteger(st.sval); }
        // dp[mask][last]: best sum for a valid prefix using mask and ending with sonu[last]; null = unreachable.
        BigInteger[][] dp = new BigInteger[1 << n][n];
        for (int j = 0; j < n; j++) dp[1 << j][j] = BigInteger.ZERO;
        for (int mask = 1; mask < (1 << n); mask++) {
            int pos = Integer.bitCount(mask) - 1;
            if (pos == n - 1) continue;
            boolean rise = ramu[pos].compareTo(ramu[pos + 1]) < 0;
            for (int last = 0; last < n; last++) {
                BigInteger score = dp[mask][last];
                if (score == null) continue;
                for (int nxt = 0; nxt < n; nxt++) {
                    if ((mask >> nxt & 1) == 1) continue;
                    int cmp = sonu[last].compareTo(sonu[nxt]);
                    if ((cmp < 0) != rise) continue;
                    BigInteger value = score.add(sonu[last].subtract(sonu[nxt]).abs());
                    int nm = mask | 1 << nxt;
                    if (dp[nm][nxt] == null || value.compareTo(dp[nm][nxt]) > 0) dp[nm][nxt] = value;
                }
            }
        }
        BigInteger best = null;
        for (BigInteger v : dp[(1 << n) - 1])
            if (v != null && (best == null || v.compareTo(best) > 0)) best = v;
        System.out.println(best);
    }
}

package main

import (
	"bufio"
	"fmt"
	"math/big"
	"math/bits"
	"os"
)

func main() {
	in := bufio.NewReader(os.Stdin)
	var n int
	fmt.Fscan(in, &n)
	// Lengths may exceed 64 bits, so use big.Int throughout.
	read := func() []*big.Int {
		a := make([]*big.Int, n)
		for i := range a {
			var s string
			fmt.Fscan(in, &s)
			a[i], _ = new(big.Int).SetString(s, 10)
		}
		return a
	}
	ramu, sonu := read(), read()
	// dp[mask][last]: best sum for a valid prefix using mask and ending with sonu[last]; nil = unreachable.
	dp := make([][]*big.Int, 1<<n)
	for i := range dp {
		dp[i] = make([]*big.Int, n)
	}
	for j := 0; j < n; j++ {
		dp[1<<j][j] = new(big.Int)
	}
	value := new(big.Int)
	for mask := 1; mask < 1<<n; mask++ {
		pos := bits.OnesCount(uint(mask)) - 1
		if pos == n-1 {
			continue
		}
		rise := ramu[pos].Cmp(ramu[pos+1]) < 0
		for last := 0; last < n; last++ {
			score := dp[mask][last]
			if score == nil {
				continue
			}
			for nxt := 0; nxt < n; nxt++ {
				if mask>>nxt&1 == 1 || (sonu[last].Cmp(sonu[nxt]) < 0) != rise {
					continue
				}
				value.Sub(sonu[last], sonu[nxt])
				value.Abs(value)
				value.Add(value, score)
				nm := mask | 1<<nxt
				if dp[nm][nxt] == nil {
					dp[nm][nxt] = new(big.Int).Set(value)
				} else if value.Cmp(dp[nm][nxt]) > 0 {
					dp[nm][nxt].Set(value)
				}
			}
		}
	}
	var best *big.Int
	for _, v := range dp[1<<n-1] {
		if v != nil && (best == nil || v.Cmp(best) > 0) {
			best = v
		}
	}
	fmt.Println(best.String())
}
